const toRad = d => d * Math.PI / 180;

const sfLat = 37.7749, sfLon = -122.4194;  // San Francisco
const bosLat = 42.3601, bosLon = -71.0589; // Boston

const R = 6371; // Earth's radius in km
const dLat = toRad(bosLat - sfLat);
const dLon = toRad(bosLon - sfLon);

const a = Math.sin(dLat/2)**2 + Math.cos(toRad(sfLat)) * Math.cos(toRad(bosLat)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const distKm = R * c;
const distMi = distKm * 0.621371;

console.log('=== Distance Calculation ===');
console.log('From: San Francisco, CA  (37.7749°N, 122.4194°W)');
console.log('To:   Boston, MA         (42.3601°N, 71.0589°W)');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  ' + distKm.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' km');
console.log('  ' + distMi.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
"
